    ('圆满', '他们的婚礼举办得非常圆满和成功。', 'viên mãn, tốt đẹp', 'yuán mǎn', '他们的婚礼举办得非常圆满和成功。', 'viên mãn, tốt đẹp', 'yuán mǎn', 'Tāmen de hūnlǐ jǔbàn de fēicháng yuánmǎn hé chénggōng.', 'Lễ cưới của họ được tổ chức rất viên mãn và thành công.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-5a9ca9d9f273f8b230b67fbd.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-2c6de7f119e7c894e865be45.mp3'),
    ('园林', '苏州的园林以其精致的设计闻名世界。', 'lâm viên, vườn', 'yuán lín', '苏州的园林以其精致的设计闻名世界。', 'lâm viên, vườn', 'yuán lín', 'Sūzhōu de yuánlín yǐ qí jīngzhì de shèjì wénmíng shìjiè.', 'Lâm viên ở Tô Châu nổi tiếng thế giới bởi thiết kế tinh tế.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-0c0c466e2f1feb9991dc94f1.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-97977ad32aceb0050e96c4c2.mp3'),
    ('原理', '这台机器的工作原理并不复杂。', 'nguyên lí', 'yuán lǐ', '这台机器的工作原理并不复杂。', 'nguyên lí', 'yuán lǐ', 'Zhè tái jīqì de gōngzuò yuánlǐ bìng bù fùzá.', 'Nguyên lý hoạt động của máy này không phức tạp.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-ea30fe51764c708fcc8228b5.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-9d232471294354951082af52.mp3'),
    ('原始', '我们参观了保存完好的原始森林。', 'nguyên thủy', 'yuán shǐ', '我们参观了保存完好的原始森林。', 'nguyên thủy', 'yuán shǐ', 'Wǒmen cānguānle bǎocún wánhǎo de yuánshǐ sēnlín.', 'Chúng tôi đã tham quan khu rừng nguyên thủy được bảo tồn nguyên vẹn.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-8cb7c0a54b21bbc3f228f04d.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-e667518c40f1ff6c354968ac.mp3'),
    ('原告', '原告在法庭上陈述了自己的诉求。', 'nguyên cáo', 'yuán gào', '原告在法庭上陈述了自己的诉求。', 'nguyên cáo', 'yuán gào', 'Yuángào zài fǎtíng shàng chénshùle zìjǐ de sùqiú.', 'Nguyên cáo đã trình bày yêu cầu của mình tại tòa án.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-0bcfe03f296428e9a50bf5ad.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-8cd545a6614644ae12c977e6.mp3'),
    ('原先', '原先计划的行程因为天气变化有所调整。', 'ban đầu', 'yuán xiān', '原先计划的行程因为天气变化有所调整。', 'ban đầu', 'yuán xiān', 'Yuánxiān jìhuà de xíngchéng yīnwèi tiānqì biànhuà yǒu suǒ tiáozhěng.', 'Lịch trình ban đầu đã được điều chỉnh vì thời tiết thay đổi.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-31f301fe7fa07709abfb03ee.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-4a4094468aea6d1dffa4c8a3.mp3'),
    ('厌恶', '他对说谎的人怀有强烈的厌恶情绪。', 'ghét', 'yàn wù', '他对说谎的人怀有强烈的厌恶情绪。', 'ghét', 'yàn wù', 'Tā duì shuōhuǎng de rén huáiyǒu qiángliè de yànwù qíngxù.', 'Anh ta có cảm giác ghét bỏ mạnh mẽ đối với người nói dối.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-f6cb90f57bc2395829e723be.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-989c9b0baa30590e869f3f98.mp3'),
    ('压迫', '那个国家的人民一直生活在压迫之下。', 'áp bức', 'yā pò', '那个国家的人民一直生活在压迫之下。', 'áp bức', 'yā pò', 'Nàgè guójiā de rénmín yīzhí shēnghuó zài yāpò zhī xià.', 'Nhân dân của đất nước đó luôn sống trong sự áp bức.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-4f856e4a2d6793dc489afa10.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-cc7646ae4b14761ce9ec5706.mp3'),
    ('压缩', '文件太大了，需要进行压缩才能发送。', 'nén', 'yā suō', '文件太大了，需要进行压缩才能发送。', 'nén', 'yā suō', 'Wénjiàn tài dà le, xūyào jìnxíng yāsuō cáinéng fāsòng.', 'Tập tin quá lớn, cần nén lại mới có thể gửi đi.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-a22879cda61a8da0219c5e2b.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-b828347a25786be6351dbcec.mp3'),
    ('压榨', '资本家常常压榨工人的劳动成果。', 'đàn áp (công nhân, người nghèo), ép', 'yā zhà', '资本家常常压榨工人的劳动成果。', 'đàn áp (công nhân, người nghèo), ép', 'yā zhà', 'Zīběnjiā chángcháng yāzhà gōngrén de láodòng chéngguǒ.', 'Tư bản chủ nghĩa thường xuyên đàn áp thành quả lao động của công nhân.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-26badc86c56b87799fe647ca.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-b2923a05871c5cfc401865c2.mp3'),
    ('压抑', '长时间的压抑让他感到身心俱疲。', 'sự đè nén, đè nén', 'yā yì', '长时间的压抑让他感到身心俱疲。', 'sự đè nén, đè nén', 'yā yì', 'Cháng shíjiān de yāyì ràng tā gǎndào shēnxīn jù pí.', 'Sự đè nén kéo dài khiến anh ta cảm thấy cả tâm hồn lẫn thể xác đều mệt mỏi.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-0b46887d16645a64af3dfd5c.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-84d8049e20e6831ef221bf0e.mp3'),
    ('压岁钱', '春节期间，孩子们都期待收到长辈的压岁钱。', 'tiền mừng tuổi', 'yā suì qián', '春节期间，孩子们都期待收到长辈的压岁钱。', 'tiền mừng tuổi', 'yā suì qián', 'Chūnjié qījiān, háizimen dōu qīdài shōudào zhǎngbèi de yāsuìqián.', 'Trong dịp Tết, các em nhỏ đều mong nhận được tiền mừng tuổi từ người lớn.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-d7702e5226e2985a235c5ba9.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-ce9c64c814ff9a7043c3dc2a.mp3'),
    ('压制', '警方采取武力压制示威者引发争议。', 'trấn áp(cuộc biểu tình)', 'yā zhì', '警方采取武力压制示威者引发争议。', 'trấn áp(cuộc biểu tình)', 'yā zhì', 'Jǐngfāng cǎiqǔ wǔlì yāzhì shìwēizhě yǐnfā zhēngyì.', 'Cảnh sát sử dụng vũ lực để trấn áp người biểu tình gây tranh cãi.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-ee9c3c199c5df377db38e337.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-45567970424eb2bf09ea13b9.mp3'),
    ('勇于', '他勇于面对生活中的各种挑战。', 'dám làm….', 'yǒng yú', '他勇于面对生活中的各种挑战。', 'dám làm….', 'yǒng yú', 'Tā yǒngyú miànduì shēnghuó zhōng de gèzhǒng tiǎozhàn.', 'Anh ta dám đối mặt với mọi thử thách trong cuộc sống.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-d6eb34c40e36cdf38e5530db.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-354223d7fac6c0cead212401.mp3'),
    ('冤枉', '他被误解而感到非常冤枉。', 'oan uổng', 'yuān wǎng', '他被误解而感到非常冤枉。', 'oan uổng', 'yuān wǎng', 'Tā bèi wùjiě ér gǎndào fēicháng yuānwang.', 'Anh ta cảm thấy rất oan uổng vì bị hiểu lầm.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-70d5a8ffec6c0f406ac74a97.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-00de6fa1a225b3c07a526b40.mp3')
)
update public.template_cards as card
set
  pinyin = repaired.pinyin,
  meaning_vi = repaired.meaning_vi,
  example_cn = repaired.example_cn,
  example_pinyin = repaired.example_pinyin,
  example_vi = repaired.example_vi,
  word_audio_url = repaired.word_audio_url,
  sentence_audio_url = repaired.sentence_audio_url
from public.template_decks as deck,
  repaired_hsk as repaired
where card.template_deck_id = deck.id
  and deck.slug = 'hsk6-co-ban'
  and card.chinese = repaired.chinese;

with repaired_hsk (
  chinese,
  original_example_cn,
  original_meaning_vi,
  original_pinyin,
