) as (
  values
    ('新陈代谢', '人的新陈代谢速度会随着年龄的增长而减慢。', 'đổi cũ thay mới', 'xīn chén dài xiè', '人的新陈代谢速度会随着年龄的增长而减慢。', 'đổi cũ thay mới', 'xīn chén dài xiè', 'Rén de xīnchén dàixiè sùdù huì suízhe niánlíng de zēngzhǎng ér jiǎnmàn.', 'Tốc độ đổi mới của cơ thể người sẽ chậm lại theo độ tuổi tăng lên.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-73009e7bd9146961f6ab5abd.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-500925e0603d0a77c6a803dd.mp3'),
    ('新郎', '在婚礼上，新郎穿着传统的中式礼服显得非常帅气。', 'chú rể', 'xīn láng', '在婚礼上，新郎穿着传统的中式礼服显得非常帅气。', 'chú rể', 'xīn láng', 'Zài hūnlǐ shàng, xīnláng chuānzhe chuántǒng de zhōngshì lǐfú xiǎnde fēicháng shuàiqì.', 'Trong đám cưới, chú rể mặc bộ lễ phục kiểu Trung truyền thống trông rất phong độ.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-d0c399bc00e3c0c4b8a36280.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-10b8d72abefe830e8aaae4cc.mp3'),
    ('新娘', '新娘披着洁白的婚纱，脸上洋溢着幸福的笑容。', 'cô dâu', 'xīn niáng', '新娘披着洁白的婚纱，脸上洋溢着幸福的笑容。', 'cô dâu', 'xīn niáng', 'Xīnniáng pīzhe jiébái de hūnshā, liǎn shàng yángyìzhe xìngfú de xiàoróng.', 'Cô dâu mặc chiếc váy cưới trắng tinh, trên mặt toát lên nụ cười hạnh phúc.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-07c723ed34a2d592dc0a0820.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-c7252ef2b3d0f7ff33f82dc8.mp3'),
    ('效益', '这家企业实行新政策后，公司的效益明显提升。', 'lợi ích', 'xiào yì', '这家企业实行新政策后，公司的效益明显提升。', 'lợi ích', 'xiào yì', 'Zhè jiā qǐyè shíxíng xīn zhèngcè hòu, gōngsī de xiàoyì míngxiǎn tíshēng.', 'Sau khi công ty thực hiện chính sách mới, hiệu quả hoạt động rõ ràng được cải thiện.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-9b6a3f30ea980070dfb1179f.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-54f974a647c0663b6c72f40d.mp3'),
    ('携带', '旅途中请务必携带有效身份证件以备检查。', 'xách theo', 'xié dài', '旅途中请务必携带有效身份证件以备检查。', 'xách theo', 'xié dài', 'Lǚtú zhōng qǐng wùbì xiédài yǒuxiào shēnfèn zhèngjiàn yǐ bèi jiǎnchá.', 'Trong chuyến đi, vui lòng mang theo giấy tờ tùy thân hợp lệ để kiểm tra.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-27da70caca83e01ca9bcd311.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-72495f5f98235f14ec47606a.mp3'),
    ('掀起', '春风掀起了湖面上的波浪，景色十分迷人。', 'vén, mở', 'xiān qǐ', '春风掀起了湖面上的波浪，景色十分迷人。', 'vén, mở', 'xiān qǐ', 'Chūnfēng xiānqǐle húmiàn shàng de bōlàng, jǐngsè shífēn mírén.', 'Gió xuân làm dạt lên những gợn sóng trên mặt hồ, cảnh sắc rất quyến rũ.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-6d027545932bb40384ef9029.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-97258fec5f1c97ffe2c0d5a2.mp3'),
